INSERT IGNORE INTO product_variants (product_id, model_id, case_type, variant_price, stock) SELECT p.product_id, m.model_id, t.case_type, IF(t.case_type = 'Tough', 125.00, 100.00), 20 FROM products p JOIN phone_models m ON m.model_name IN ('iPhone 11','iPhone 11 Pro','iPhone 11 Pro Max','iPhone 12','iPhone 12 Pro','iPhone 12 Pro Max','iPhone 13','iPhone 13 Pro','iPhone 13 Pro Max','iPhone 14','iPhone 14 Plus','iPhone 14 Pro','iPhone 14 Pro Max','iPhone 15','iPhone 15 Plus','iPhone 15 Pro','iPhone 15 Pro Max','iPhone 16','iPhone 16 Plus','iPhone 16 Pro','iPhone 16 Pro Max') JOIN (SELECT 'Standard' AS case_type UNION ALL SELECT 'Tough') t WHERE p.product_slug = 'truth-white';
